window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-41001\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τὠστία</h1><div class=\"entry-meta\"><span>DGP · ordem 1543 na letra τ · nº geral 41001</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de τὰ ὀστία, forma dór. de τὰ ὀστέα.</p></section></article>\n<article id=\"entry-dgp-41002\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τὦτα</h1><div class=\"entry-meta\"><span>DGP · ordem 1544 na letra τ · nº geral 41002</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase poét. de τὰ ὦτα.</p></section></article>\n<article id=\"entry-dgp-41003\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τωὐτ’</h1><div class=\"entry-meta\"><span>DGP · ordem 1545 na letra τ · nº geral 41003</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase dór. de τὸ αὐτό em elisão.</p></section></article>\n<article id=\"entry-dgp-41004\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τωὐτό, τωὐτέου, τωὐτῷ</h1><div class=\"entry-meta\"><span>DGP · ordem 1546 na letra τ · nº geral 41004</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase jôn. de τὸ αὐτό, τοῦ αὐτοῦ, τῷ αὐτῷ.</p></section></article>\n<article id=\"entry-dgp-41005\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τὠ᾽ φθαλμώ</h1><div class=\"entry-meta\"><span>DGP · ordem 1547 na letra τ · nº geral 41005</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">elisão poét. e át. τὼ ὀφθαλμώ.</p></section></article>\n<article id=\"entry-dgp-41006\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τῷ᾽ χλῳ</h1><div class=\"entry-meta\"><span>DGP · ordem 1548 na letra τ · nº geral 41006</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">elisão poét. e át. de τῷ ὄχλῳ.</p></section></article>\n<article id=\"entry-dgp-41007\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Υ, υ (ὗ ψιλόν) (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 1 na letra υ · nº geral 41007</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ípsilon, 20a letra do alfabeto ♦ num. 2 υʹ = 400 ou 400o 3 ͵υ = 400.000 ou 400.000o.</p></section></article>\n<article id=\"entry-dgp-41008\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὔ</h1><div class=\"entry-meta\"><span>DGP · ordem 2 na letra υ · nº geral 41008</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ou ὕ ou ὔ ὗ interj. (expressão de admiração ou espanto) huhu! Ὑάδες, ων (αἱ) Híades, lit. “chuvosas”, grupo de estrelas da constelação de Touro. 〈ὕω〉</p></section></article>\n<article id=\"entry-dgp-41009\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕαινα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 3 na letra υ · nº geral 41009</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 hiena 2 espécie de linguado, peixe. 〈ὗς〉 Ὑακίνθια, ων (τά) Jacíntias, festas realizadas na Lace­demônia em honra de Jacinto. 〈 Ὑάκινθος〉 Ὑακινθινοβαφής, ής, ές tingido de azul violeta, a cor do jacinto. 〈ὑακίνθινος, βάπτω〉</p></section></article>\n<article id=\"entry-dgp-41010\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑακίνθινος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 4 na letra υ · nº geral 41010</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">da cor do jacinto; violeta ou azul escuro. 〈ὑάκινθος〉</p></section></article>\n<article id=\"entry-dgp-41011\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑάκινθος, ου (ὁ</h1><div class=\"entry-meta\"><span>DGP · ordem 5 na letra υ · nº geral 41011</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἡ) 1 jacinto, flor violeta ou azul 2 veste ou tecido da cor de jacinto 3 pedra preciosa da cor do jacinto ♦ masc. Ὑάκινθος 4 Jacinto, n. de h.</p></section></article>\n<article id=\"entry-dgp-41012\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑάλινος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 6 na letra υ · nº geral 41012</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de vidro; de cristal. 〈ὕαλος〉</p></section></article>\n<article id=\"entry-dgp-41013\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑαλοειδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 7 na letra υ · nº geral 41013</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">semelhante ao vidro; vítreo; cristalino. 〈ὕαλος, εἶδος〉</p></section></article>\n<article id=\"entry-dgp-41014\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕαλος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 8 na letra υ · nº geral 41014</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 qualquer pedra transparente (alabastro, cristal etc.) 2 vidro.</p></section></article>\n<article id=\"entry-dgp-41015\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑββάλλειν</h1><div class=\"entry-meta\"><span>DGP · ordem 9 na letra υ · nº geral 41015</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. pres. ép. de ὑποβάλλω.</p></section></article>\n<article id=\"entry-dgp-41016\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑβρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 10 na letra υ · nº geral 41016</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ὑβρίσω, át. ὑβριῶ, aor. ὕβρισα, perf. ὕβρικα, m.-q.-perf. ὑβρίκειν; pas. fut. ὑβρισθήσομαι, aor. ὑβρίσθην, perf. ὕβρισμαι, m.-q.-perf. ὑβρίσμην) 1 entregar-se a excessos: ἐκ τῶν ἡμετέρων ὑβρίζειν dem. entregar-se a excessos às nossas custas 2 ser presunçoso ou insolente; falar ou agir com orgulho 3 comportar-se de modo dissoluto; dar-se aos prazeres sensuais 4 (não humano) agitar-se violentamente, de maneira desenfreada: οἵ τε ὑβρισταὶ ἵπποι ἐκτεμνόμενοι τοῦ μὲν δάκνειν καὶ ὑβρίζειν ἀποπαύονται xen. os cavalos bravos, depois de castrados, deixam de morder e de rebelar-se 5 cometer insolências ou violências contra alguém, εἰς, πρός, κατά e ac., ἐπί e dat.: ὑβρίζειν ἐς τοὺς θεούς ar. insultar os deuses, ὕβρεις ἃς κατὰ τὴν ἀγορὰν ὕβριζεν dem. ultrajes que ousou cometer contra a assembleia, ὕβριν θ᾽ ὑβρίζεις ἐπὶ θανοῦσι τοῖς ἐμοῖς eur. praticas insolências sobre os meus mortos 6 praticar com violência (uma ação); exceder-se em algo, ac.: τῶν ἀδικημάτων δοῦναι δίκας, τῶν ἐς Ἀθηναίους ὕβρισαν her. expiar as faltas que insolentemente cometeram contra os atenienses, ὅσα λόγῳ καὶ ὅσα ἔργῳ περὶ θεοὺς ὑβρίζει τις plat. todos os ultrajes que em palavras e em ações cometem-se contra deuses 7 tratar com insolência; injuriar; maltratar; ultrajar algo ou alguém, ac.: ὑβρίζειν τοὺς ὑβρίζοντας ésql. ultrajar os ultrajantes 8 submeter alguém, ac., a violência, ac.: ἡμᾶς ὑβρίζειν τοιάνδ᾽ ὕβριν eur. submeter-nos a tal ultraje ♦ pas. 9 sofrer, suportar um ultraje: τάλαιν᾽ ἐγὼ τῆς ὕβρεος, ἧς ὑβρίζομαι ar. infeliz que sou! que ultraje estou sofrendo! ὕβριν ὑβρίζεσθαι eur. suportar maus tratos 10 sofrer agressão: ὑβρισμένος τὰς γνάθους ar. agredido no queixo 11 (eunuco) ser mutilado 12 (coisa) ser pomposo, faustoso: στολὴ οὐδέν τι ὑβρισμένη xen. vestimenta que nada tem de pomposa. 〈ὕβρις〉</p></section></article>\n<article id=\"entry-dgp-41017\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕβρις, εως(ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 11 na letra υ · nº geral 41017</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 tudo o que ultrapassa a medida; excesso 2 orgulho; insolência: ὕβριν τῖσαι hom. expiar sua insolência, sua audácia, ὕβρει ou δι’ ὕβριν, εἰς ὕβριν, πρὸς ὕβριν, ἐφ᾽ ὕβρει por orgulho 3 pl. pensamentos ou atos soberbos 4 ardor excessivo; arrebatamento; ímpeto; insolência; violência: ὅθιπερ πάρος ὕβριν ἔχεσκον hom. lá justamente onde outrora praticavam sua insolência, ὕβρει εἷξαι hom. entregar-se, abandonar-se à insolência 5 fervura ou fermentação: ὕβρις οἴνου el. fermentação do vinho 6 fogosidade; ímpeto 7 ato de desespero 8 ultraje; injúria; insulto 9 violência física (contra mulher ou criança); violência sexual 10 Jur. sevícias: ὕβρεως δίκη ou γραφή processo por sevícias 11 bíbl. dano ♦ Ὕβρις 12 Violência; Insolência, person. 〈ὑπέρ〉</p></section></article>\n<article id=\"entry-dgp-41018\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕβρισμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 12 na letra υ · nº geral 41018</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ultraje; maus-tratos; violência 2 objeto de ultraje ou de violência. 〈ὑβρίζω〉</p></section></article>\n<article id=\"entry-dgp-41019\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑβριστής, οῦ</h1><div class=\"entry-meta\"><span>DGP · ordem 13 na letra υ · nº geral 41019</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 arrebatado; colérico; insolente; descomedido 2 impetuoso; violento (vento, rio) 3 dado aos prazeres; dissoluto; incontinente. 〈ὑβρίζω〉</p></section></article>\n<article id=\"entry-dgp-41020\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑβριστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 14 na letra υ · nº geral 41020</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que se entrega a excessos; dado a excessos 2 coberto de vegetação luxuriante 3 insolente; arrogante; violento; arrebatado 4 impudico; ultrajante 5 referente à violência, aos maus-tratos ♦ τὸ ὑβριστικόν 6 insolência; violência ♦ τὰ Ὑβριστικά 7 festa comemorada em Argos, em honra de Afrodite, com trocas de vestes entre homens e mulheres. 〈ὑβριστής〉</p></section></article>\n<article id=\"entry-dgp-41021\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑβριστικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 15 na letra υ · nº geral 41021</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com arrogância; insolentemente; violentamente.</p></section></article>\n<article id=\"entry-dgp-41022\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕβριστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 16 na letra υ · nº geral 41022</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ὑβριστικός. Ὑγεία, ας (ἡ) = Ὑγίεια.</p></section></article>\n<article id=\"entry-dgp-41023\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑγιᾶ</h1><div class=\"entry-meta\"><span>DGP · ordem 17 na letra υ · nº geral 41023</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. sing. contr. de ὑγιής.</p></section></article>\n<article id=\"entry-dgp-41024\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑγιάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 18 na letra υ · nº geral 41024</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. pas. ὑγιάσθην) 1 tornar são ou bem de saúde 2 intr. recuperar a saúde 3 intr., (ferida) curar-se; sarar ♦ pas. 4 restabelecer-se; curar-se. 〈ὑγιής〉</p></section></article>\n<article id=\"entry-dgp-41025\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑγιαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 19 na letra υ · nº geral 41025</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ὑγιανῶ, aor. ὑγίανα, perf. desus.; pas. fut. ὑγιασθήσομαι, aor. ὑγιάσθην e ὑγιάνθην, perf. desus.) 1 estar são; estar em bom estado de saúde; ter saúde: ὑγίαινε passar bem!, fórmula de saudação, partic. de adeus 2 (coisa) estar em bom estado 3 ter o espírito sadio, são; estar em seu perfeito juízo 4 curar-se; sarar; restabelecer-se 5 curar alguém ou algo ♦ pas. 6 restabelecer-se ♦ τὸ ὑγιαῖνον 7 a condição sadia; sanidade. 〈ὑγιής〉</p></section></article>\n<article id=\"entry-dgp-41026\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑγίεια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 20 na letra υ · nº geral 41026</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 saúde; boa saúde 2 pl. boas condições de saúde 3 cura ♦ Ὑίεια 4 Higia; Saúde, deusa. 〈ὑγιής〉</p></section></article>\n<article id=\"entry-dgp-41027\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑγιεινός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 21 na letra υ · nº geral 41027</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que favorece a saúde; salubre; salutar 2 que está bem de saúde; são; saudável 3 concernente à saúde ♦ τὸ ὑγιεινόν 4 saúde 5 pl. coisas salutares. 〈ὑγιής〉</p></section></article>\n<article id=\"entry-dgp-41028\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑγιεινῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 22 na letra υ · nº geral 41028</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 em bom estado de saúde; saudavelmente: ὑ. ἔχειν estar bem de saúde 2 de maneira salutar 3 sadiamente; retamente; corretamente.</p></section></article>\n<article id=\"entry-dgp-41029\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑγιηρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 23 na letra υ · nº geral 41029</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que tem saúde; que está são; saudável 2 que cura; salutar. 〈ὑγιής〉</p></section></article>\n<article id=\"entry-dgp-41030\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑγιής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 24 na letra υ · nº geral 41030</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que está bem de saúde; são; sadio; saudável: ὑγιὲς σῶμα xen. corpo são, ἐν χρόνῳ ὀλίγῳ ὑγιέα μιν ἀπέδεξε her. em pouco tempo o pôs sadio 2 que recuperou a saúde; restabelecido de algo, ac.: τὸ δῆγμα ὑγιής xen. curado da mordida 3 não danificado; intacto; inteiro (coisa) 4 forte; sadio; vigoroso (espírito) 5 são; sensato; irrepreensível (juízo, caráter): εἴ τι ὑγιὲς διανοοῦνται tuc. se concebem algo sensato, οὐδὲν ὑγιὲς φρονεῖν sóf. não ter no espírito nada de sensato, οὐδὲν ὑγιὲς διανοεῖσθαι tuc. não pensar nada de bom, ter intenções pérfidas, desleais, ὑγιὲς οὐδὲν λέγω τῶν ὀργίων eur. digo que não há nada de sensato nos ritos ♦ τὸ ὑγιές 6 saúde; sanidade.</p></section></article>\n<article id=\"entry-dgp-41031\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑγιῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 25 na letra υ · nº geral 41031</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em bom estado; saudavelmente.</p></section></article>\n<article id=\"entry-dgp-41032\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑγρά, ᾶς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 26 na letra υ · nº geral 41032</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ὑγρός.</p></section></article>\n<article id=\"entry-dgp-41033\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑγροποιός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 27 na letra υ · nº geral 41033</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que umedece; que molha. 〈ὑγρός, ποιέω〉</p></section></article>\n<article id=\"entry-dgp-41034\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑγρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 28 na letra υ · nº geral 41034</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 molhado; úmido: γῆ ὑγρά xen. região úmida, ὑγρὸς πόθος hin. desejo voluptuoso 2 que escorre; líquido: ἔλαιον ὑγρόν hom. óleo de oliva, ὑγρὸν ὕδωρ hom. água que corre ou escorre na mão, ὑγρὰ κέλευθα hom. líquidos caminhos, i.e., o mar 3 úmido; chuvoso (noite) 4 que é da umidade, da água; aquático (animal) 5 mole; flutuante; flácido; murcho 6 tenro; delicado (filhote) 7 ébrio; embriagado 8 flexível; macio; dobrável: ὑγρὰ ἔχειν τὰ σκέλη xen. ter as pernas flexíveis, ágeis 9 facilmente inclinado a, dat.: ὑγρὸς τῷ γελοίῳ plut. inclinado ao ridículo 10 flácido; murcho; sem força: ὑ. ἀγκών sóf. braço sem força 11 frouxo; efeminado; sensual 12 em forma de onda; onduloso (som) 13 vacilante 14 relaxado; solto (intestino) ♦ ἡ ὑγρά, jôn. ὑγρή 15 mar ♦ τὸ ὑγρόν 16 umidade; líquido: ἐφ᾽ ὑγροῖς ζωγραφεῖν plut. pintar, desenhar a fresco 17 humor; secreção ♦ ὑγρόν adv. 18 com umidade: ἄνεμοι ὑγρὸν ἀέντες hom. ventos que sopram com umidade, ventos chuvosos.</p></section></article>\n<article id=\"entry-dgp-41035\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑγρότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 29 na letra υ · nº geral 41035</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 umidade; transpiração pouco abundante; fluidez 2 agilidade; flexibilidade 3 leviandade de caráter; sensualidade 4 fraqueza: ὑ. τῆς χειρός sóf. fraqueza da mão que segura uma espada. 〈ὑγρός〉</p></section></article>\n<article id=\"entry-dgp-41036\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑγρώσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 30 na letra υ · nº geral 41036</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) estar úmido. 〈ὑγρός〉</p></section></article>\n<article id=\"entry-dgp-41037\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδαρής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 31 na letra υ · nº geral 41037</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aguado; aquoso; fraco (vinho) 2 fraco; enfraquecido 3 descorado (cor) 4 adulterado (metal) 5 vil. 〈ὕδωρ〉</p></section></article>\n<article id=\"entry-dgp-41038\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕδασι</h1><div class=\"entry-meta\"><span>DGP · ordem 32 na letra υ · nº geral 41038</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. pl. de ὕδωρ.</p></section></article>\n<article id=\"entry-dgp-41039\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδατόκλυστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 33 na letra υ · nº geral 41039</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">lavado com água. 〈ὕδωρ, κλύζω〉</p></section></article>\n<article id=\"entry-dgp-41040\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδατοποσία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 34 na letra υ · nº geral 41040</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de beber água. 〈ὕδωρ, πίνω〉</p></section></article>\n<article id=\"entry-dgp-41041\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδατοποτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 35 na letra υ · nº geral 41041</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">beber água. 〈ὕδωρ, πίνω〉</p></section></article>\n<article id=\"entry-dgp-41042\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδατοτρεφής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 36 na letra υ · nº geral 41042</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que cresce à beira da água; que se nutre de água. 〈ὕδωρ, τρέφω〉</p></section></article>\n<article id=\"entry-dgp-41043\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδατώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 37 na letra υ · nº geral 41043</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 da cor ou da natureza da água; aquoso 2 que derrete e vira água 3 que contém água; cheio de água; úmido 4 Medic. hidrópico (pessoa) 5 úmido; chuvoso (inverno). 〈ὕδωρ〉</p></section></article>\n<article id=\"entry-dgp-41044\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδεριάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 38 na letra υ · nº geral 41044</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Medic. estar hidrópico. 〈ὕδερος〉</p></section></article>\n<article id=\"entry-dgp-41045\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕδερος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 39 na letra υ · nº geral 41045</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Medic. hidropsia.</p></section></article>\n<article id=\"entry-dgp-41046\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕδνον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 40 na letra υ · nº geral 41046</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">espécie de tubérculo, talvez trufa ou túbera.</p></section></article>\n<article id=\"entry-dgp-41047\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕδρα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 41 na letra υ · nº geral 41047</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 hidra, serpente de água ♦ Ὕδρα 2 Hidra de Lerna, monstro: prov. Ὕδραν τέμνειν plat. decapitar a Hidra, i.e., fazer um trabalho inútil 3 Hidra, constelação. 〈ὕδωρ〉</p></section></article>\n<article id=\"entry-dgp-41048\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδραγωγός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 42 na letra υ · nº geral 41048</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que conduz ou leva a água 2 que traz chuva 3 Medic. diurético 4 Medic. hidrópico ♦ ὁ ὑδραγωγός 5 encarregado do serviço das águas; inspetor de aqueduto 6 aqueduto. 〈ὕδωρ, ἄγω〉</p></section></article>\n<article id=\"entry-dgp-41049\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδραίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 43 na letra υ · nº geral 41049</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 molhar; regar; irrigar 2 derramar; verter ♦ méd. (part. aor. ὑδρηναμένη) 3 derramar água sobre si; banhar-se. 〈ὕδωρ〉</p></section></article>\n<article id=\"entry-dgp-41050\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδρεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 44 na letra υ · nº geral 41050</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fornecimento de água 2 ação de regar; irrigação 3 água de irrigação 4 lugar de onde se tira água; reservatório de água. 〈ὑδρεύω〉</p></section></article>\n<article id=\"entry-dgp-41051\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδρεῖον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 45 na letra υ · nº geral 41051</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 recipiente para tirar água; balde 2 reservatório de água; cisterna 3 clepsidra. 〈ὕδωρ〉</p></section></article>\n<article id=\"entry-dgp-41052\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδρέλαιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 46 na letra υ · nº geral 41052</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mistura de água e óleo. 〈ὕδωρ, ἔλαιον〉</p></section></article>\n<article id=\"entry-dgp-41053\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδρεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 47 na letra υ · nº geral 41053</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 fazer provisão de água; fazer aguada 2 regar; irrigar ♦ méd. 3 abastecer-se de água. 〈ὕδωρ〉</p></section></article>\n<article id=\"entry-dgp-41054\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδρήϊον</h1><div class=\"entry-meta\"><span>DGP · ordem 48 na letra υ · nº geral 41054</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ὑδρεῖον.</p></section></article>\n<article id=\"entry-dgp-41055\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδρηλός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 49 na letra υ · nº geral 41055</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 úmido; banhado de água 2 que serve para tirar água. 〈ὕδωρ〉</p></section></article>\n<article id=\"entry-dgp-41056\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 50 na letra υ · nº geral 41056</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 recipiente para tirar, conter ou verter água 2 jarro para vinho 3 cofre para guardar dinheiro 4 urna para as cinzas dos mortos 5 urna para votar no tribunal. 〈ὕδωρ〉</p></section></article>\n<article id=\"entry-dgp-41057\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδροθήρας, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 51 na letra υ · nº geral 41057</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pescador. 〈ὕδωρ, θηράω〉</p></section></article>\n<article id=\"entry-dgp-41058\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδροθηρία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 52 na letra υ · nº geral 41058</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pesca. 〈ὕδωρ, θηράω〉</p></section></article>\n<article id=\"entry-dgp-41059\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδροθηρικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 53 na letra υ · nº geral 41059</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de pesca ou de pescador. 〈ὕδωρ, θηράω〉</p></section></article>\n<article id=\"entry-dgp-41060\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδρονομέομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 54 na letra υ · nº geral 41060</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) reclamar sua porção de água.</p></section></article>\n<article id=\"entry-dgp-41061\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδροποιός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 55 na letra υ · nº geral 41061</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que produz ou conduz água. 〈ὕδωρ, ποιέω〉</p></section></article>\n<article id=\"entry-dgp-41062\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδροποσία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 56 na letra υ · nº geral 41062</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">hábito de beber somente água. 〈ὑδρο­πότης〉</p></section></article>\n<article id=\"entry-dgp-41063\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδροποτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 57 na letra υ · nº geral 41063</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">beber somente água. 〈ὑδροπότης〉</p></section></article>\n<article id=\"entry-dgp-41064\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδροπότης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 58 na letra υ · nº geral 41064</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pessoa que bebe água; bebedor de água. 〈ὕδωρ, πίνω〉</p></section></article>\n<article id=\"entry-dgp-41065\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδρορρόα, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 59 na letra υ · nº geral 41065</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 conduto de água; canal; cano; tubo 2 goteira; biqueira. 〈ὕδωρ, ῥοή〉</p></section></article>\n<article id=\"entry-dgp-41066\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕδρος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 60 na letra υ · nº geral 41066</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 serpente de água; hidra 2 pequeno animal aquático. 〈ὕδωρ〉</p></section></article>\n<article id=\"entry-dgp-41067\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδροφόβας, α (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 61 na letra υ · nº geral 41067</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Medic. hidrofobia. 〈ὕδωρ, φόβος〉</p></section></article>\n<article id=\"entry-dgp-41068\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδροφορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 62 na letra υ · nº geral 41068</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">levar água. 〈ὑδροφόρος〉</p></section></article>\n<article id=\"entry-dgp-41069\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδροφορία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 63 na letra υ · nº geral 41069</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de levar água. 〈ὑδροφόρος〉</p></section></article>\n<article id=\"entry-dgp-41070\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδροφόρος, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 64 na letra υ · nº geral 41070</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 que traz ou carrega água ♦ ὁ e ἡ ὑδροφόρος 2 aguadeiro; aguadeira. 〈ὕδωρ, φέρω〉 Ὑδροχοεύς, έως (ὁ) Aquário, lit. “vertedor de água”, signo do Zodíaco. 〈ὕδωρ, χέω〉 Ὑδροχόος, ου (ὁ) = Ὑδροχοεύς.</p></section></article>\n<article id=\"entry-dgp-41071\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδρωπιάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 65 na letra υ · nº geral 41071</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Medic. ser hidrópico. 〈ὕδρωψ〉</p></section></article>\n<article id=\"entry-dgp-41072\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑδρωπικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 66 na letra υ · nº geral 41072</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Medic. hidrópico. 〈ὕδρωψ〉</p></section></article>\n<article id=\"entry-dgp-41073\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕδρωψ, ωπος</h1><div class=\"entry-meta\"><span>DGP · ordem 67 na letra υ · nº geral 41073</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 hidrópico ♦ ὁ ὕδρωψ 2 Medic. hidropsia 3 Medic. humor aquoso 4 líquido amniótico. 〈ὕδωρ, ὤψ〉</p></section></article>\n<article id=\"entry-dgp-41074\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕδωρ, ὕδατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 68 na letra υ · nº geral 41074</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 água: γῆ καὶ ὕδωρ αἰτεῖν her. exigir a terra e a água como sinal de dominação, γῆν καὶ ὕδωρ διδόναι her. entregar a terra e a água, i.e., submeter-se, subjugar-se, prov. καθ᾽ ὕδατος γράφειν luc. escrever na água, i.e., fazer esforços ou trabalhos inúteis 2 água potável: prov. ὕδωρ πίνειν beber água, i.e., estar inerte, ser insosso, ser incapaz de grandes pensamentos 3 água para banho 4 água da clepsidra; tempo de fala concedido: ἐν τῷ ἐμῷ ὕδατι dem. durante o escoamento de minha água, i.e., durante o tempo de fala que me é garantido pela clepsidra, ἀποδιδόναι τινὶ τὸ ὕδωρ dem. conceder a palavra a alguém, ὑπὲρ τὸ ἐγχεόμενον ὕδωρ para além da água escoada, i.e., do tempo concedido 5 tempo disponível para, inf.: πρὸς ὕδωρ σμικρὸν διδάξαι plat. com pouco tempo para ensinar, ensinar em pouco tempo, ἐὰν τὸ ὕδωρ ἐγχωρῇ dem. se o tempo permite 6 transpiração; suor: ἐν ὕδατι βρέχεσθαι her. estar molhado, encharcado de suor 7 chuva: γίγνεται ὕδωρ her. começa a chover 8 líquido 9 Astron. Água, parte da constelação de Aquário.</p></section></article>\n<article id=\"entry-dgp-41075\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕειος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 69 na letra υ · nº geral 41075</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de porco; suíno ♦ τὰ ὕεια 2 carne de porco. 〈ὗς〉</p></section></article>\n<article id=\"entry-dgp-41076\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑέλινος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 70 na letra υ · nº geral 41076</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ὑάλινος.</p></section></article>\n<article id=\"entry-dgp-41077\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑέτιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 71 na letra υ · nº geral 41077</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de chuva; plúvio 2 que traz chuva; chuvoso. 〈ὑετός〉</p></section></article>\n<article id=\"entry-dgp-41078\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑετός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 72 na letra υ · nº geral 41078</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">chuva forte, ininterrupta. 〈ὕω〉</p></section></article>\n<article id=\"entry-dgp-41079\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑετώτατος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 73 na letra υ · nº geral 41079</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ὑετιώτατος, superl. de ὑέτιος. Ὕης e Ὑῆς, οῦ (ὁ) Hies, provavelmente “o úmido, o fecundante”, epít. de Dioniso. 〈ὕω〉</p></section></article>\n<article id=\"entry-dgp-41080\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑθλέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 74 na letra υ · nº geral 41080</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dizer tolices; tagarelar. 〈ὕθλος〉</p></section></article>\n<article id=\"entry-dgp-41081\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕθλος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 75 na letra υ · nº geral 41081</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ditos fúteis; futilidades; tagarelice; falatório.</p></section></article>\n<article id=\"entry-dgp-41082\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">υἷα</h1><div class=\"entry-meta\"><span>DGP · ordem 76 na letra υ · nº geral 41082</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. sing., υἱάσι dat. pl., de υἱός.</p></section></article>\n<article id=\"entry-dgp-41083\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">υἵδιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 77 na letra υ · nº geral 41083</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filhinho. 〈υἱός〉</p></section></article>\n<article id=\"entry-dgp-41084\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑΐδιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 78 na letra υ · nº geral 41084</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">porquinho. 〈ὗς〉</p></section></article>\n<article id=\"entry-dgp-41085\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑϊδοῦς, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 79 na letra υ · nº geral 41085</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">neto. 〈υἱός〉</p></section></article>\n<article id=\"entry-dgp-41086\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">υἷϊ</h1><div class=\"entry-meta\"><span>DGP · ordem 80 na letra υ · nº geral 41086</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dat. sing. poét. de υἱός.</p></section></article>\n<article id=\"entry-dgp-41087\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">υἱϊδεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 81 na letra υ · nº geral 41087</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">neto. 〈υἱός〉</p></section></article>\n<article id=\"entry-dgp-41088\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑϊκός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 82 na letra υ · nº geral 41088</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de porco; suíno: ὑϊκόν τι πάσχειν xen. sentir algo próprio de um porco, i.e., vontade de esfregar-se a algo. 〈ὗς〉</p></section></article>\n<article id=\"entry-dgp-41089\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">υἱοθεσία, ας</h1><div class=\"entry-meta\"><span>DGP · ordem 83 na letra υ · nº geral 41089</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adoção como filho. 〈υἱοθετέω〉</p></section></article>\n<article id=\"entry-dgp-41090\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">υἱοθετέω</h1><div class=\"entry-meta\"><span>DGP · ordem 84 na letra υ · nº geral 41090</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adotar como filho. 〈υἱός, τίθημι〉</p></section></article>\n<article id=\"entry-dgp-41091\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">υἷος</h1><div class=\"entry-meta\"><span>DGP · ordem 85 na letra υ · nº geral 41091</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">υἱός.</p></section></article>\n<article id=\"entry-dgp-41092\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">υἱός, υἱοῦ</h1><div class=\"entry-meta\"><span>DGP · ordem 86 na letra υ · nº geral 41092</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e υἱέος (ὁ) 1 filho 2 pl. filhos; descendentes enquanto uma classe de homens, gen.: υἷες Ἀχαιῶν hom. os filhos dos aqueus, i.e., os gregos, υἷες ἰατρῶν ou ῥητόρων os filhos dos médicos ou dos oradores, i.e., os médicos, os oradores 3 genro.</p></section></article>\n<article id=\"entry-dgp-41093\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">υἱωνός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 87 na letra υ · nº geral 41093</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">neto. 〈υἱός〉</p></section></article>\n<article id=\"entry-dgp-41094\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὕλαγμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 88 na letra υ · nº geral 41094</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 latido; ladrido 2 vociferação. 〈ὑλάσσω〉</p></section></article>\n<article id=\"entry-dgp-41095\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑλαγμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 89 na letra υ · nº geral 41095</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">latido; ladrido. 〈ὑλάσσω〉</p></section></article>\n<article id=\"entry-dgp-41096\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑλάεις</h1><div class=\"entry-meta\"><span>DGP · ordem 90 na letra υ · nº geral 41096</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = ὑλήεις.</p></section></article>\n<article id=\"entry-dgp-41097\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑλαῖος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 91 na letra υ · nº geral 41097</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de bosque; de floresta 2 que vive na selva; selvagem. 〈ὕλη〉</p></section></article>\n<article id=\"entry-dgp-41098\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑλακή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 92 na letra υ · nº geral 41098</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">latido; ladrido. 〈ὑλάω〉</p></section></article>\n<article id=\"entry-dgp-41099\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑλακόμωρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 93 na letra υ · nº geral 41099</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que late sem cessar ou furiosamente. 〈ὑλακή, -μωρος〉</p></section></article>\n<article id=\"entry-dgp-41100\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ὑλακτέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 94 na letra υ · nº geral 41100</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 latir; ladrar 2 lançar gritos terríveis (cólera ou dor) 3 (coração, estômago) produzir grande ruído 4 perseguir com latidos 5 perseguir com injúrias ou maldições. 〈ὑλάω〉</p></section></article>\n";
